function postReceiving(e){e.preventDefault();if(!requireProfile()||!requiredDate('receive-date')||!requiredNumber('receive-qty','Quantity received',true)||!requiredNumber('receive-cost','Unit cost'))return;const item=itemById($('receive-item').value),loc=$('receive-location').value,q=qty($('receive-qty').value),cost=num($('receive-cost').value),ref=$('receive-reference').value.trim(),date=$('receive-date').value||today();if(!item||!loc||q<=0){setStatus('Choose an item, location, and quantity greater than zero.',true);return}if(!confirmDate(date))return;if(cost!==item.cost&&!confirm(`Change ${item.name} cost from ${money(item.cost)} to ${money(cost)} per ${item.unit}? This revalues all remaining stock.`))return;const ok=mutate(()=>{const old=item.cost;addLocationBalance(item,loc,q);item.cost=cost;recordMovement({type:'receiving',date,itemId:item.id,toLocation:loc,qty:q,unitCost:cost,reference:ref});if(num(old)!==cost)recordCost(item,old,cost,ref||'Receiving',date)},`${item.name}: ${q} ${item.unit} received into ${locName(loc)}.`);if(ok){$('receive-qty').value='';$('receive-reference').value=''}}
function movementMode(){const a=$('move-action').value,transfer=a==='transfer';$('move-to-label').style.display=transfer?'grid':'none';$('movement-help').textContent=transfer?'Transfers move stock between locations without changing total on-hand.':a==='adjustment-plus'?'Positive adjustment adds stock to the selected location.':'This action reduces stock from the selected location and records the reason in history.'}
function postMovement(e){e.preventDefault();if(!requireProfile()||!requiredDate('move-date')||!requiredNumber('move-qty','Movement quantity',true))return;if(!$('move-reason').value.trim()){setStatus('Enter a reason or reference before posting a movement.',true);$('move-reason').focus();return}const action=$('move-action').value,item=itemById($('move-item').value),from=$('move-from').value,to=$('move-to').value,q=qty($('move-qty').value),date=$('move-date').value||today(),ref=$('move-reason').value.trim();if(!item||!from||q<=0){setStatus('Choose an item, location, and quantity greater than zero.',true);return}if(action==='transfer'&&(!to||to===from)){setStatus('Choose a different destination location for the transfer.',true);return}const available=locationBalance(item,from);if(action!=='adjustment-plus'&&q>available+.0005){setStatus(`Only ${available} ${item.unit} of ${item.name} is available in ${locName(from)}.`,true);return}if(!confirmDate(date))return;const ok=mutate(()=>{if(action==='transfer'){addLocationBalance(item,from,-q);addLocationBalance(item,to,q);recordMovement({type:'transfer',date,itemId:item.id,fromLocation:from,toLocation:to,qty:q,unitCost:item.cost,reference:ref})}else if(action==='adjustment-plus'){addLocationBalance(item,from,q);recordMovement({type:'adjustment-plus',date,itemId:item.id,toLocation:from,qty:q,unitCost:item.cost,reference:ref})}else{addLocationBalance(item,from,-q);recordMovement({type:action,date,itemId:item.id,fromLocation:from,qty:q,unitCost:item.cost,reference:ref})}},`${labelType(action)} posted for ${item.name}.`);if(ok){$('move-qty').value='';$('move-reason').value=''}}
