async function exportItems(){const header=['Item ID','Item','Category','Vendor','SKU','Barcode','Unit','Case Pack','Unit Cost','Yield %','Par','Reorder Point','On Hand','Primary Location','Active'];const rows=state.items.map(i=>[i.id,i.name,i.category,i.vendor,i.sku,i.barcode,i.unit,i.casePack,i.cost,i.yieldPct,i.par,i.reorder,totalOnHand(i),locName(i.primaryLocation),i.active!==false?'Yes':'No']);await saveText(`Gravity_Inventory_Item_Master_${today()}.csv`,[header,...rows].map(r=>r.map(csvEscape).join(',')).join('\n'))}
