const glossaryEntries={
'Active item':'An inventory item currently available for routine receiving, counting and movement. An inactive item keeps its history.',
'Barcode':'A scannable product or internal identifier. Inventory Center can use an existing product code or a restaurant-created internal code.',
'Case pack':'Reference quantity normally purchased together. Your count unit and unit cost still control inventory value.',
'Count unit':'The unit you physically count and price, such as each, lb, bottle or case.',
'Cycle count':'A physical count of selected items or locations instead of the entire restaurant.',
'Full count':'A physical count intended to cover every stocked item in the selected scope.',
'Inventory value':'Current on-hand quantity multiplied by the current unit cost for each item.',
'Item master':'The controlled list of inventory items and their units, locations, costs, pars, barcodes and status.',
'Latest cost':'The current unit cost used by this workspace for present inventory value. Cost history remains available separately.',
'Location':'A real place where stock can physically exist, such as a walk-in, shelf, freezer, bar cage or prep area.',
'Par':'The target quantity you normally want available.',
'Primary location':'The item’s usual storage location. The same item may also have balances in other locations.',
'Receiving':'Recording inventory that arrived, including quantity, cost, actual source and receipt/reference information.',
'Reorder point':'The quantity at or below which Inventory Center flags the item when stock is also below par.',
'Transfer':'Moving stock between locations without changing the restaurant’s total quantity or value.',
'Variance':'The difference between the system quantity and the physical quantity counted.',
'Waste / spill / comp':'A recorded reason stock left usable inventory outside a normal sale or transfer.'};
let importPreview=null;
