function renderSales(){state.sales=Array.isArray(state.sales)?state.sales:[];const rows=[...state.sales].sort((a,b)=>b.date.localeCompare(a.date));$('sales-days').textContent=rows.length;$('sales-total').textContent=money(rows.reduce((s,r)=>s+num(r.netSales),0));$('sales-summary-title').textContent=rows.length?`${rows.length} recorded sales day${rows.length===1?'':'s'}`:'No sales days recorded';$('sales-range').textContent=rows.length?`Date range: ${rows[rows.length-1].date} through ${rows[0].date}`:'Add a sales day to begin the range.';$('sales-list').innerHTML=rows.map(r=>`<div class="stack-item"><div><strong>${esc(r.date)}</strong><small>${esc(r.note||'Recorded net sales')}</small></div><span class="badge good">${money(r.netSales)}</span></div>`).join('')||'<div class="empty-state">No recorded sales days yet.</div>'}
function recordSales(e){e.preventDefault();if(!requireProfile())return;const date=$('sales-date').value,raw=$('sales-net').value.trim(),net=Number(raw);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))){setStatus('Enter a valid sales date.',true);return}if(raw===''||!Number.isFinite(net)||net<0||net>1e9){setStatus('Enter net sales from zero to 1,000,000,000.',true);return}const note=$('sales-note').value.trim();mutate(()=>{state.sales=Array.isArray(state.sales)?state.sales:[];const old=state.sales.find(r=>r.date===date);if(old){old.netSales=net;old.note=note}else state.sales.push({id:uid('sale'),date,netSales:net,note,createdAt:new Date().toISOString()})},`Sales for ${date} recorded.`);renderSales()}
