function downloadImportTemplate(){saveText('Gravity_Inventory_Item_Import_Template.csv',['Item,Category,Vendor,SKU,Barcode,Unit,Case Pack,Unit Cost,Yield %,Par,Reorder Point,Primary Location,Opening On Hand,Active','Tomatoes,Produce,Walmart,TOM-01,,lb,1,1.25,100,30,10,Walk-in Cooler,12,Yes','Fryer Oil,Food,US Foods,OIL-35,012345678901,jug,4,24.00,100,8,3,Dry Storage,5,Yes'].join('\n'))}
